TYPE.TEST:


SetFunctionName("Soa4Vector4()");

Soa4Vector4 v;

Validate( true ); // Take address of v so that it is referenced


SetFunctionName("Soa4Vector4(const Soa4Vector4&)");

Soa4Vector4 ref( mA );

Validate( IsEqual( ref, mA ) );


SetFunctionName("Soa4Vector4(Soa4Float)");

Soa4Vector4 ref( Soa4FloatFromFloat( 1.0f ) );

Validate( IsEqual( ref, mOne ) );



SetFunctionName("Soa4Vector4(VectorIntrinsic)");

VectorIntrinsic vx, vy, vz, vw;
vx = Soa4FloatFromFloat( 1.0f ).mV;
vy = Soa4FloatFromFloat( 1.0f ).mV;
vz = Soa4FloatFromFloat( 1.0f ).mV;
vw = Soa4FloatFromFloat( 1.0f ).mV;

Soa4Vector4 ref( vx, vy, vz, vw );

Validate( IsEqual( ref, mOne ) );


SetFunctionName("Soa4Vector4 operator=(const Soa4Vector4&)");

Soa4Vector4 ref( mZero );
Validate( !IsEqual( ref, mOne ) );

ref = mOne;

Validate( IsEqual( ref, mOne ) );
Validate( &ref.x != &mOne.x && &ref.y != &mOne.y && &ref.z != &mOne.z && &ref.w != &mOne.w );


SetFunctionName("X()");

Soa4Vector4 ref( mNegOne );

const Soa4Float& cx = ref.X();
Validate( IsEqual( cx, ref.x ) );

Soa4Float& x = ref.X();

x = Soa4FloatFromFloat( 1.0f );

Validate( !IsEqual( ref, mOne ) );
Validate( IsEqual( ref.x, Soa4FloatFromFloat(  1.0f ) ) );
Validate( IsEqual( ref.y, Soa4FloatFromFloat( -1.0f ) ) );
Validate( IsEqual( ref.z, Soa4FloatFromFloat( -1.0f ) ) );
Validate( IsEqual( ref.w, Soa4FloatFromFloat( -1.0f ) ) );


SetFunctionName("Y()");

Soa4Vector4 ref( mNegOne );

const Soa4Float& cy = ref.Y();
Validate( IsEqual( cy, ref.y ) );

Soa4Float& y = ref.Y();

y = Soa4FloatFromFloat( 1.0f );

Validate( !IsEqual( ref, mOne ) );
Validate( IsEqual( ref.x, Soa4FloatFromFloat( -1.0f ) ) );
Validate( IsEqual( ref.y, Soa4FloatFromFloat(  1.0f ) ) );
Validate( IsEqual( ref.z, Soa4FloatFromFloat( -1.0f ) ) );            
Validate( IsEqual( ref.w, Soa4FloatFromFloat( -1.0f ) ) );


SetFunctionName("Z()");

Soa4Vector4 ref( mNegOne );

const Soa4Float& cz = ref.Z();
Validate( IsEqual( cz, ref.z ) );

Soa4Float& z = ref.Z();

z = Soa4FloatFromFloat( 1.0f );

Validate( !IsEqual( ref, mOne ) );
Validate( IsEqual( ref.x, Soa4FloatFromFloat( -1.0f ) ) );
Validate( IsEqual( ref.y, Soa4FloatFromFloat( -1.0f ) ) );
Validate( IsEqual( ref.z, Soa4FloatFromFloat(  1.0f ) ) );            
Validate( IsEqual( ref.w, Soa4FloatFromFloat( -1.0f ) ) );


SetFunctionName("W()");

Soa4Vector4 ref( mNegOne );

const Soa4Float& cw = ref.W();
Validate( IsEqual( cw, ref.w ) );

Soa4Float& w = ref.W();

w = Soa4FloatFromFloat( 1.0f );

Validate( !IsEqual( ref, mOne ) );
Validate( IsEqual( ref.x, Soa4FloatFromFloat( -1.0f ) ) );
Validate( IsEqual( ref.y, Soa4FloatFromFloat( -1.0f ) ) );
Validate( IsEqual( ref.z, Soa4FloatFromFloat( -1.0f ) ) );            
Validate( IsEqual( ref.w, Soa4FloatFromFloat(  1.0f ) ) );


SetFunctionName("Soa4Vector4FromVector4(Vector4::InParam v)");

Vector4 v( 1.0f, -1.0f, 2.0f, -2.0f );
Soa4Vector4 sv = Soa4Vector4FromVector4( v );
Validate( IsEqual( sv.x, Soa4FloatFromFloat(  1.0f ) ) );
Validate( IsEqual( sv.y, Soa4FloatFromFloat( -1.0f ) ) );
Validate( IsEqual( sv.z, Soa4FloatFromFloat(  2.0f ) ) );
Validate( IsEqual( sv.w, Soa4FloatFromFloat( -2.0f ) ) );


SetFunctionName("Soa4Vector4FromVector4(Vector4::InParam v0, Vector4::InParam v1, Vector4::InParam v2, Vector4::InParam v3)");

// These are the same values as in the member vector "mA"
Vector4 v0( -1.0f, 5.0f, 0.25f, 10.0f );
Vector4 v1(  2.0f, 3.0f, 1.0f, 0.125f );
Vector4 v2(  3.0f, 3.0f, 3.0f, 3.0f );
Vector4 v3( -4.0f, 1.0f, -10.0f, 0.0f );

Soa4Vector4 sv = Soa4Vector4FromVector4( v0, v1, v2, v3 );

Validate( IsEqual( sv, mA ) );


SetFunctionName("Soa4Vector4FromVector4(const Vector4*)");

// These are the same values as in the member vector "mA"
Vector4 v[4] = {
    Vector4( -1.0f, 5.0f, 0.25f, 10.0f ),
    Vector4(  2.0f, 3.0f, 1.0f, 0.125f ),
    Vector4(  3.0f, 3.0f, 3.0f, 3.0f ),
    Vector4( -4.0f, 1.0f, -10.0f, 0.0f )
};

Soa4Vector4 sv = Soa4Vector4FromVector4( v );

Validate( IsEqual( sv, mA ) );


SetFunctionName("Vector4FromSoa4Vector4(Soa4Vector4::InParam, Vector4& v0, Vector4& v1, Vector4& v2, Vector4& v3)");
Vector4 v0, v1, v2, v3;
Vector4 rv0( -1.0f, 5.0f, 0.25f, 10.0f );
Vector4 rv1(  2.0f, 3.0f, 1.0f, 0.125f );
Vector4 rv2(  3.0f, 3.0f, 3.0f, 3.0f );
Vector4 rv3( -4.0f, 1.0f, -10.0f, 0.0f );

Vector4FromSoa4Vector4( mA, v0, v1, v2, v3 );
Validate( IsEqual( v0, rv0 ) );
Validate( IsEqual( v1, rv1 ) );
Validate( IsEqual( v2, rv2 ) );
Validate( IsEqual( v3, rv3 ) );


SetFunctionName("Vector4FromSoa4Vector4(Soa4Vector4::InParam, Vector4* v)");
Vector4 v[4];
Vector4 rv0( -1.0f, 5.0f, 0.25f, 10.0f );
Vector4 rv1(  2.0f, 3.0f, 1.0f, 0.125f );
Vector4 rv2(  3.0f, 3.0f, 3.0f, 3.0f );
Vector4 rv3( -4.0f, 1.0f, -10.0f, 0.0f );

Vector4FromSoa4Vector4( mA, v );
Validate( IsEqual( v[0], rv0 ) );
Validate( IsEqual( v[1], rv1 ) );
Validate( IsEqual( v[2], rv2 ) );
Validate( IsEqual( v[3], rv3 ) );


