SetFunctionName("SLerp(Soa4Vector4::InParam v0, Soa4Vector4::InParam v1, Soa4Float::InParam t)");

{
    Soa4Vector4 a( Soa4FloatFromFloat( 1.0f ), Soa4FloatFromFloat( 2.0f ), Soa4FloatFromFloat( 3.45f ), Soa4FloatFromFloat( 2.1f) );
    Soa4Vector4 b( Soa4FloatFromFloat( -3.0f ), Soa4FloatFromFloat( 1.0f ), Soa4FloatFromFloat( 5.3f ), Soa4FloatFromFloat( 2.1f ) );
    Soa4Float slerpT( Soa4FloatFromFloats( 0.75f, 0.75f, 0.75f, 0.75f ) );
    Soa4Vector4 normalA = Normalize( a );
    Soa4Vector4 normalB = Normalize( b );

    Soa4Vector4 output = SLerp( normalA, normalB, slerpT );

    Soa4Vector4 slerpRef( Soa4FloatFromFloat( -0.30123767f ), 
        Soa4FloatFromFloat( 0.23916793f ),
        Soa4FloatFromFloat( 0.84240395f ),
        Soa4FloatFromFloat( 0.37737280f ) );
    Validate( IsEqualWithEpsilon( output, slerpRef, 0.02f ) );
}

