{
    VectorIntrinsic r[4] = {
        CreateSoa4Float( 1.0f, 1.0f, 1.0f, 1.0f ).mV,
        CreateSoa4Float( 2.0f, 2.0f, 2.0f, 2.0f ).mV,
        CreateSoa4Float( 0.5f, 0.5f, 0.5f, 0.5f ).mV,
        CreateSoa4Float( 0.25f, 0.25f, 0.25f, 0.25f ).mV
    };
    Soa4Vector4 range( r[0], r[1], r[2], r[3] );
    Soa4Vector4 res = ClampToNegPosRange( mA, range );
    VectorIntrinsic v[4] = {
        CreateSoa4Float( -1.0f, 1.0f, 1.0f, -1.0f ).mV,
        CreateSoa4Float( 2.0f, 2.0f, 2.0f, 1.0f ).mV,
        CreateSoa4Float( 0.25f, 0.5f, 0.5f, -0.5f ).mV,
        CreateSoa4Float( 0.25f, 0.125f, 0.25f, 0.0f ).mV
    };
    Soa4Vector4 ref( v[0], v[1], v[2], v[3] );

    Validate( IsEqual( res, ref ) );
}


