SetFunctionName("CosAngleBetweenNormalizedVectors(Soa4Vector4::InParam v0, Soa4Vector4::InParam v1)");

{
    Soa4Vector4 normalizedA = Normalize( mA );
    Soa4Vector4 normalizedB = Normalize( mB );
    Soa4Float refAngle = Dot( normalizedA, normalizedB );
    Soa4Float res = CosAngleBetweenNormalizedVectors( normalizedA, normalizedB );

    Validate( IsEqual( refAngle, res ) );
}



